import { useState } from 'react';
import Navbar from '../components/Navbar';
import TransactionForm from '../components/TransactionForm';
import TransactionList from '../components/TransactionList';
import SummaryCard from '../components/SummaryCard';
import InvestmentForm from '../components/InvestmentForm';
import InvestmentList from '../components/InvestmentList';
import Tabs from '../components/Tabs';
import styles from './Dashboard.module.css';

const Dashboard = () => {
  const [transactions, setTransactions] = useState([]);
  const [investments, setInvestments] = useState([]);
  const [activeTab, setActiveTab] = useState(0);
  const [currentBalance, setCurrentBalance] = useState(310000);

  // Calcular ingresos y gastos regulares (excluyendo transacciones de inversión)
  const regularIncome = transactions
    .filter(t => t.type === 'income' && !t.isInvestmentRelated)
    .reduce((sum, t) => sum + parseFloat(t.amount || 0), 0);

  const regularExpenses = transactions
    .filter(t => t.type === 'expense' && !t.isInvestmentRelated)
    .reduce((sum, t) => sum + parseFloat(t.amount || 0), 0);

  // Calcular ganancias/pérdidas netas de inversiones
  const netInvestmentProfit = investments.reduce(
    (sum, inv) => sum + (parseFloat(inv.salePrice || 0) - parseFloat(inv.initialCost || 0)),
    0
  );

  // Totales generales
  const totalIncome = regularIncome + Math.max(0, netInvestmentProfit);
  const totalExpenses = regularExpenses + Math.max(0, -netInvestmentProfit);
  const netProfit = totalIncome - totalExpenses;

  // Función para agregar transacción regular
  const handleAddTransaction = (transaction) => {
    const newTransaction = { 
      ...transaction, 
      amount: parseFloat(transaction.amount),
      isInvestmentRelated: false
    };
    
    setTransactions(prev => [...prev, newTransaction]);
    
    // Actualizar balance actual
    setCurrentBalance(prev => 
      newTransaction.type === 'income' 
        ? prev + newTransaction.amount 
        : prev - newTransaction.amount
    );
  };

  // Función para agregar inversión
  const handleAddInvestment = (investment) => {
    const newInvestment = {
      ...investment,
      initialCost: parseFloat(investment.initialCost),
      salePrice: parseFloat(investment.salePrice),
    };
    
    setInvestments(prev => [...prev, newInvestment]);

    // Registrar costo inicial como gasto (marcado como relacionado a inversión)
    const costTransaction = {
      description: `Compra de laptop (${investment.brand})`,
      amount: newInvestment.initialCost,
      type: 'expense',
      isInvestmentRelated: true,
      date: new Date().toISOString().split('T')[0]
    };
    
    setTransactions(prev => [...prev, costTransaction]);
    
    // Actualizar balance con el costo
    setCurrentBalance(prev => prev - newInvestment.initialCost);

    // Si hay ganancia/pérdida al vender, registrar transacción adicional
    if (newInvestment.salePrice > 0) {
      const profit = newInvestment.salePrice - newInvestment.initialCost;
      const profitTransaction = {
        description: profit > 0 
          ? `Ganancia por laptop (${investment.brand})` 
          : `Pérdida por laptop (${investment.brand})`,
        amount: Math.abs(profit),
        type: profit > 0 ? 'income' : 'expense',
        isInvestmentRelated: true,
        date: new Date().toISOString().split('T')[0]
      };
      
      setTransactions(prev => [...prev, profitTransaction]);
      
      // Actualizar balance con la ganancia/pérdida
      setCurrentBalance(prev => profit > 0 ? prev + profit : prev - Math.abs(profit));
    }
  };

  const handleEditInvestment = (index) => {
    console.log('Edit investment:', investments[index]);
  };

  // Definir pestañas
  const tabs = ['Resumen', 'Transacciones', 'Inversiones'];

  return (
    <div>
      <Navbar />
      <div className={styles.dashboard}>
        <h1>Control de Negocios</h1>
        <Tabs tabs={tabs} activeTab={activeTab} onTabChange={setActiveTab} />

        {activeTab === 0 && (
          <div className={styles.summaryCard}>
            <SummaryCard
              totalIncome={totalIncome}
              totalExpenses={totalExpenses}
              balance={netProfit}
              currentBalance={currentBalance}
            />
          </div>
        )}

        {activeTab === 1 && (
          <div className={styles.transactionSection}>
            <h2>Transacciones</h2>
            <TransactionForm onAddTransaction={handleAddTransaction} />
            <TransactionList transactions={transactions} />
          </div>
        )}

        {activeTab === 2 && (
          <div className={styles.investmentSection}>
            <h2>Inversiones en Laptops</h2>
            <InvestmentForm onAddInvestment={handleAddInvestment} />
            <InvestmentList
              investments={investments}
              onEditInvestment={handleEditInvestment}
            />
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
